function searchScreen(){
 const r=searchAll(data,globalQuery),companyLabel=id=>id?esc(companyName(id)):'Général';
 const section=(title,res,item,more='')=>`<section class="card search-group"><h3>${title} <span class="muted">· ${res.total}</span></h3>${res.total?`<ul class="search-list">${res.items.map(item).join('')}</ul>${res.total>res.items.length?`<p class="muted small">${res.items.length} premiers résultats affichés sur ${res.total} : précisez la recherche.</p>`:''}${more}`:'<p class="muted">Aucun résultat.</p>'}</section>`;
 const head=`${heading('Recherche','Sociétés, tâches, notes et échéances : tous les mots saisis doivent apparaître, accents et majuscules ignorés.')}<div class="toolbar"><label class="search-field">Rechercher partout<input id="global-search" type="search" value="${esc(globalQuery)}" placeholder="Nom, intitulé, contact, catégorie…" autocomplete="off"></label></div>`;
 if(!r)return head+'<p class="empty">Saisissez un ou plusieurs mots.</p>';
 const total=r.companies.total+r.tasks.total+r.notes.total+r.deadlines.total;
 return head+`<p class="muted" role="status">${total} résultat(s) pour « ${esc(globalQuery)} »</p><div class="search-results">`
  +section('Sociétés',r.companies,c=>`<li><button data-company-detail="${c.id}"><strong>${esc(c.name)}</strong><small>${esc([c.contact,c.email,c.phone].filter(Boolean).join(' · '))||'Fiche société'}</small></button></li>`)
  +section('Tâches',r.tasks,t=>`<li><button data-edit-task="${t.id}"><strong>${esc(t.title)}</strong><small>${companyLabel(t.companyId)} · ${t.dueDate?esc(t.dueDate):'Sans date'} · ${t.status==='done'?'Terminée':t.status==='in_progress'?'En cours':'À faire'}</small></button></li>`,`<button class="text-action" data-search-tasks>Voir ces tâches dans la liste filtrable</button>`)
  +section('Notes',r.notes,n=>`<li><button data-edit-note="${n.id}"><strong>${esc(n.title||n.content.split(/\r?\n/)[0].slice(0,80))}</strong><small>${companyLabel(n.companyId)}${n.deletedAt?' · dans la corbeille':''}</small></button></li>`)
  +section('Échéances',r.deadlines,d=>`<li><button data-edit-deadline="${d.id}"><strong>${esc(d.title)}</strong><small>${companyLabel(d.companyId)} · ${esc(d.dueDate)} · ${esc(d.category||'Sans catégorie')}${d.status==='done'?' · terminée':''}</small></button></li>`)
  +'</div>';
}
// Chiffrement des sauvegardes : clé de synchronisation si déverrouillée, sinon phrase de sauvegarde
// saisie une fois par session (gardée en mémoire seulement). Préférence « Chiffrer » par appareil.
async function protectBackup(text,id,override){
 if(!readBackupInfo().encrypt)return {text,encrypted:false};
 let k=override||sync.backupKey()||sessionBackupKey;
 if(!k&&id==='download-backup'&&($('backup-pass')?.value||$('backup-pass2')?.value)){k=await backupKeyFromPassphrase($('backup-pass').value,$('backup-pass2')?.value||'');sessionBackupKey=k;renderEncryption();}
 if(!k)return {text,encrypted:false,reason:id==='download-backup'?'aucune phrase saisie':'aucune phrase disponible pour la chiffrer'};
 return {text:await encryptBackupText(text,k),encrypted:true};
}
function renderEncryption(){if($('backup-encryption'))$('backup-encryption').innerHTML=encryptionHTML({encrypt:readBackupInfo().encrypt,syncKey:!!sync.backupKey(),sessionKey:!!sessionBackupKey});}
function backupNeedsPassphrase(){return readBackupInfo().encrypt&&!sync.backupKey()&&!sessionBackupKey;}
async function openBackupFile(text){
 if(!isEncryptedBackup(text))return text;
 const kdf=envelopeKdf(text),same=k=>k&&k.kdf.salt===kdf.salt&&k.kdf.iterations===kdf.iterations;
 const k=[sync.backupKey(),sessionBackupKey].find(same);
 if(k)return decryptBackupText(text,{key:k.key});
 const passphrase=$('restore-pass')?.value||'';if(!passphrase)throw Error('Sauvegarde chiffrée : saisissez sa phrase.');
 return decryptBackupText(text,{passphrase});
}
let data=emptyState(),store,route='home',companyFilter='',taskScope='all',query='',busy=false,ready=false,editing=null,restore=null,safetyRevision=null;
function error(message){if($('editor').open&&message){$('form-error').textContent=message;$('form-error').hidden=false;$('error').hidden=true;}else{$('error').textContent=message;$('error').hidden=!message;}if(!message){$('form-error').textContent='';$('form-error').hidden=true;}}
function status(message){$('status').textContent=message;}
function setBusy(value){busy=value;$('save-editor').disabled=value;$('create-trigger').disabled=value||!ready;document.body.setAttribute('aria-busy',String(value));document.querySelectorAll('.routine-step input,.routine-step select,.routine-step button,#routine-model-form input,#routine-model-form textarea,#routine-model-form button,#routine-start,#routine-close,#routine-preview,#routine-carry-confirm').forEach(b=>{if(value){b.dataset.busyDisabled=String(b.disabled);b.disabled=true;}else if(b.dataset.busyDisabled!==undefined){b.disabled=b.dataset.busyDisabled==='true';delete b.dataset.busyDisabled;}});}
function dateToday(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
const companyName=id=>data.companies.find(c=>c.id===id)?.name||'Général · sans société';
const normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
let companyQuery='',companyDetail=null,dateFrom='',dateTo='',dateField='dueDate',doneFrom=localToday().slice(0,7)+'-01',doneTo=localToday();
let calendarKind='all';
let taskMode=readPreferences().taskMode||'list',calendarPeriod='month',calendarAnchor=localToday(),kanbanColumn='all',groupCompanies=false,priorityFilter='';
function workspace(){return taskWorkspace(tasksForView(),{mode:taskMode,period:calendarPeriod,anchor:calendarAnchor,column:kanbanColumn,group:groupCompanies,row,companyName,deadlineItems:deadlineSelection(data,companyFilter),calendarKind,extraFilters:deadlineFiltersHTML(data)});}
let routineDashboardDate=monday(localToday());
let dashboardDrill=null,dashboardGranularity='week',seriesPage=0;
function commonFilters(){return {companyId:companyFilter,scope:taskScope,query,priority:priorityFilter,dateFrom,dateTo,dateField};}
function dashboard(){return dashboardModel(data.tasks,data.companies,commonFilters(),dashboardGranularity);}
function tasksForView(){const list=selectTasks(data.tasks,{...commonFilters(),companies:data.companies});if(!dashboardDrill)return list;const ids=new Set(dashboard().groups.find(g=>g.key===dashboardDrill)?.ids||[]);return list.filter(t=>ids.has(t.id));}
function drillNotice(){if(!dashboardDrill)return '';const group=dashboard().groups.find(g=>g.key===dashboardDrill);return `<div class="helper drill-notice"><strong>Détail du tableau de bord : ${esc(group?.label||'Périmètre vide')} · ${tasksForView().length} tâche(s)</strong><p>Ce critère s’ajoute aux filtres visibles et se recalcule après modification.</p><button data-route="dashboard">Retour au tableau de bord</button><button id="clear-dashboard-drill">Retirer ce détail</button></div>`;}
function routineOverview(){const models=data.routines.models.filter(m=>!companyFilter||m.companyId===companyFilter);return `<section class="card routine-overview"><div class="card-header"><div><p class="eyebrow">Checklist hebdomadaire</p><h3>Avancement des routines</h3></div><label>Semaine · lundi<input id="routine-dashboard-date" type="date" value="${routineDashboardDate}"></label></div><p class="helper small">Société et semaine ci-dessus. Les filtres propres aux tâches ne s’appliquent pas à ces checklists ; les pourcentages restent séparés.</p><div class="company-bars">${models.map(m=>{const w=data.routines.weeks.find(w=>w.companyId===m.companyId&&w.startDate===routineDashboardDate),p=w&&progress(w);return `<button class="chart-bar" data-routine-company="${m.companyId}" data-routine-date="${routineDashboardDate}"><span class="bar-caption"><strong>${esc(companyName(m.companyId))}</strong><span>${p?`${p.done}/${p.applicable} · ${p.percent===null?'Non calculable':p.percent+' %'} · ${w.closed?'Clôturée':'Ouverte'}`:'Non démarrée'}</span></span>${p?`<progress max="100" value="${p.percent??0}" aria-hidden="true"></progress>`:''}</button>`;}).join('')||'<p>Aucune routine configurée dans ce périmètre.</p>'}</div><button data-route="routines">Ouvrir les routines</button></section>`;}
function dashboardScreen(){return dashboardHTML(dashboard(),{filtersHTML:taskFilters(),revision:data.revision,companyName:companyFilter?companyName(companyFilter):'Toutes les sociétés',granularity:dashboardGranularity,page:seriesPage})+routineOverview();}
function row(t){return `<article class="task-row" data-task-id="${t.id}"><div class="task-copy"><strong class="${t.status==='done'?'done-title':''}">${esc(t.title)}</strong><small>${esc(companyName(t.companyId))} · ${t.dueDate?esc(t.dueDate):'Sans date'} · ${priorities[t.priority]} · ${t.status==='done'?'Terminée':taskStatuses[t.status]}</small>${t.notes?`<small>${esc(t.notes)}</small>`:''}</div><div class="task-actions">${statusControl(t)}<button data-edit-task="${t.id}">Modifier</button><button data-toggle-task="${t.id}">${t.status==='done'?'Rouvrir':'Terminer'}</button></div></article>`;}
function rows(list){return list.length?list.map(row).join(''):'<p class="empty">Aucune tâche dans cette sélection.</p>';}
const heading=(title,sub,action='')=>`<div class="page-heading"><div><p class="eyebrow">Votre espace SGC</p><h2>${title}</h2><p>${sub}</p></div>${action}</div>`;
function home(){
 const today=localToday(), base={companyId:companyFilter,companies:data.companies,today};
 const pick=scope=>selectTasks(data.tasks,{...base,scope:scope==='done-period'?'done':scope,...(scope==='done-period'?{dateFrom:doneFrom,dateTo:doneTo,dateField:'completedAt'}:{})});
 const dateLabel=new Intl.DateTimeFormat('fr-FR',{weekday:'long',day:'numeric',month:'long'}).format(new Date());
 const dayTasks=pick('today').sort((a,b)=>(b.priority==='high')-(a.priority==='high'));
 const upcoming=pick('upcoming').sort((a,b)=>a.dueDate.localeCompare(b.dueDate));
 const preview=(list,scope)=>`${rows(list.slice(0,3))}${list.length>3?`<button class="text-action" data-scope="${scope}">Voir les ${list.length} tâches ${icon('arrow')}</button>`:''}`;
 return `${heading('Bonjour Hamza <span class="wave" aria-hidden="true">👋</span>',`Voici vos priorités du jour. <span class="greeting-meta">${esc(dateLabel)} · ${companyFilter?esc(companyName(companyFilter)):'Toutes vos sociétés'}</span>`)}
 <div class="dashboard-entry"><button data-route="routines">Routines hebdomadaires</button><button class="primary" data-route="dashboard">Ouvrir le tableau de bord</button><span class="muted small">Avancement, priorités et terminaisons · détails interactifs</span></div><div class="kpis home-kpis">${[['Aujourd’hui','today','calendar'],['En attente','open','tasks'],['À venir · 7 jours','upcoming','arrow'],['Sans date','undated','note'],['En retard','history','calendar'],['Terminées · période','done-period','tasks']].map(([label,scope,symbol])=>`<button class="kpi glass" data-scope="${scope}"><span class="kpi-label">${icon(symbol)}${label}</span><strong>${pick(scope).length}</strong><small>Voir le détail ${icon('arrow')}</small></button>`).join('')}</div>
 <details class="completion-period" ${mobileMedia.matches?'':'open'}><summary>Terminées sur une période · ${pick('done-period').length}</summary><div class="period-fields"><label>Du<input id="done-from" type="date" value="${doneFrom}"></label><label>Au<input id="done-to" type="date" value="${doneTo}"></label>${doneFrom>doneTo?'<p class="warning">La date de début doit précéder la fin.</p>':''}<button class="text-action" data-scope="done-period">Voir les tâches terminées ${icon('arrow')}</button></div></details><div class="columns home-columns"><section class="card today-card"><div class="card-header"><div><p class="eyebrow">L’essentiel aujourd’hui</p><h3>Priorités du jour</h3></div><button class="text-action" data-scope="today">Tout voir ${icon('arrow')}</button></div>${dayTasks.length?preview(dayTasks,'today'):'<p class="empty">Aucune tâche prévue aujourd’hui.<br><small>Les tâches sans date restent accessibles dans leur carte.</small></p>'}</section>
 <section class="card"><div class="card-header"><div><p class="eyebrow">Anticiper sereinement</p><h3>Prochaines échéances</h3></div><button class="text-action" data-scope="upcoming">Tout voir ${icon('arrow')}</button></div><p class="muted small">Dates des tâches · demain à J+7</p>${upcoming.length?preview(upcoming,'upcoming'):'<p class="empty">Aucune tâche à échéance dans les sept prochains jours.</p>'}</section></div>
 ${organiserHome(data,companyFilter)}<section class="company-shortcuts"><div class="card-header"><h3>Mes sociétés</h3><button class="text-action" data-route="companies">Tout voir ${icon('arrow')}</button></div><div class="shortcut-list">${data.companies.length?data.companies.slice(0,4).map(c=>`<button data-company-detail="${c.id}"><span class="company-avatar">${esc(c.name.slice(0,1))}</span><span>${esc(c.name)}</span>${icon('arrow')}</button>`).join(''):`<button data-open-create="true">Créer votre première société ${icon('plus')}</button>`}</div></section><div class="home-footer"><button class="history-link" data-scope="history">${icon('tasks')} Retards antérieurs <strong>${pick('history').length}</strong>${icon('arrow')}</button><span class="muted small">Conservés à part, sans encombrer votre journée.</span><button class="text-action" data-route="backup">${icon('backup')} Sauvegarder mes données</button></div>`;
}
function taskFilters(){return `<div class="toolbar"><label>Rechercher<input id="task-search" type="search" placeholder="Titre, notes, société…" value="${esc(query)}"></label><label>État tâches<select id="task-scope">${[['all','Toutes'],['open','Non terminées'],['todo','À faire'],['in_progress','En cours'],['undated','Sans date · à faire'],['done','Terminées'],['today','Aujourd’hui'],['upcoming','À venir · 7 jours'],['history','Retards antérieurs']].map(([value,label])=>`<option value="${value}" ${value===taskScope?'selected':''}>${label}</option>`).join('')}</select></label><label>Du<input id="filter-from" type="date" value="${dateFrom}"></label><label>Au<input id="filter-to" type="date" value="${dateTo}"></label><label>Date utilisée<select id="date-field"><option value="dueDate" ${dateField==='dueDate'?'selected':''}>Échéance</option><option value="completedAt" ${dateField==='completedAt'?'selected':''}>Terminaison</option></select></label><label>Priorité<select id="priority-filter">${[['','Toutes'],...Object.entries(priorities)].map(([v,l])=>`<option value="${v}" ${priorityFilter===v?'selected':''}>${l}</option>`).join('')}</select></label><button id="reset-filters">Réinitialiser</button></div>${dateFrom&&dateTo&&dateFrom>dateTo?'<p class="helper warning">Période invalide : le début doit précéder la fin.</p>':''}`;}
function taskScreen(){return `${heading('Tâches','Une seule collection de tâches · Liste, Kanban et Calendrier.','<div class="actions"><button data-export-open>Exporter cette sélection</button><button data-route="dashboard">Tableau de bord</button></div>')}${taskFilters()}${drillNotice()}<section class="card"><div class="card-header"><h3 id="task-count">${tasksForView().length} tâche(s)</h3><span class="tag">${companyFilter?esc(companyName(companyFilter)):'Toutes sociétés'}</span></div><div id="task-results">${workspace()}</div></section>`;}
function companyScreen(){
 const selected=data.companies.find(c=>c.id===companyDetail);
 if(selected){const count=data.tasks.filter(t=>t.companyId===selected.id&&t.status!=='done').length;
 return `${heading(esc(selected.name),'Fiche Société complète · à enrichir à votre rythme',`<div class="actions"><button data-edit-company="${selected.id}">Modifier la société</button><button data-delete-company="${selected.id}">Supprimer</button><button data-export-open>Exporter la fiche</button></div>`)}<button class="text-action" id="back-companies">← Toutes les sociétés</button><div class="columns company-detail"><section class="card"><p class="eyebrow">Identification & contact</p><dl class="company-fields">${[['Nom',selected.name],['Contact',selected.contact],['Email',selected.email],['Téléphone',selected.phone],['Notes',selected.notes]].map(([l,v])=>`<div><dt>${l}</dt><dd>${esc(v)||'Non renseigné'}</dd></div>`).join('')}</dl></section><section class="card"><p class="eyebrow">Travailler dans ce contexte</p><button class="company-task-link" data-company-tasks="${selected.id}"><strong>${count}</strong><span>Tâches à faire ${icon('arrow')}</span></button><button data-company-notes="${selected.id}">Notes de la société</button><button data-company-deadlines="${selected.id}">Échéances de la société</button><button data-routine-company="${selected.id}">Routines de la société</button><button class="primary" data-context-create="${selected.id}">+ Créer pour ${esc(selected.name)}</button><p class="helper small">La société sera proposée automatiquement dans le formulaire de tâche.</p></section></div><div class="e1-detail-grid">${companySections(selected)}</div>`;}
 const list=data.companies.filter(c=>(!companyFilter||c.id===companyFilter)&&(!companyQuery||normalize(`${c.name} ${c.contact} ${c.email} ${c.phone}`).includes(normalize(companyQuery))));
 return `${heading('Mes sociétés','Retrouvez vos contacts, ouvrez une fiche et créez dans son contexte.')}<div class="toolbar"><label>Rechercher une société<input id="company-search" type="search" value="${esc(companyQuery)}" placeholder="Nom, contact, email…"></label><span class="muted">${list.length} société(s)</span></div><div class="company-grid">${list.length?list.map(c=>`<article class="card company-card"><div class="company-card-head"><span class="company-avatar">${esc(c.name.slice(0,1))}</span><div><h3>${esc(c.name)}</h3><small>${esc(c.contact)||'Contact à compléter'}</small></div></div><p class="company-contact">${esc(c.email)||'Email non renseigné'}<br>${esc(c.phone)||'Téléphone non renseigné'}</p><div class="actions"><button data-company-detail="${c.id}">Ouvrir la fiche ${icon('arrow')}</button><button data-edit-company="${c.id}" aria-label="Modifier la société ${esc(c.name)}">Modifier</button><button data-delete-company="${c.id}" aria-label="Supprimer la société ${esc(c.name)}">Supprimer</button></div></article>`).join(''):`<section class="card empty"><h3>${companyQuery?'Aucune société correspondante':'Votre espace commence ici'}</h3><p>Créez une société avec son nom seulement.</p><button data-open-create="true" class="primary">+ Créer</button></section>`}</div>`;
}
function backupScreen(){return `${heading('Sauvegarde et restauration','Sociétés, tâches, routines et documents embarqués dans un fichier complet.')}<div class="columns"><section class="card"><h3>Sauvegarder une copie externe</h3><p class="helper">${data.companies.length} société(s) · ${data.tasks.length} tâche(s) · ${data.routines.weeks.length} semaine(s) de routine · ${data.notes.length} note(s) · ${data.deadlines.length} échéance(s) · révision ${data.revision}. Format JSON versionné avec empreinte d’intégrité.</p><button data-testid="backup-download" id="download-backup" class="primary">Télécharger la sauvegarde complète</button><p class="screen-divider muted">Choisissez un dossier hors du profil Chrome. Gardez la copie récente et la précédente. Vérifiez le fichier téléchargé avant de fermer l’application.</p><div id="backup-encryption"></div><div id="backup-info" class="screen-divider">${backupInfoHTML()}</div><button class="screen-divider" id="request-persistence">Demander la conservation du stockage</button><div id="persistence-status">${protectionHTML(storageProtected)}</div><p class="muted small">Version de l’application : ${APP_VERSION}</p></section><section class="card"><h3>Restaurer avec contrôle</h3><ol class="steps"><li>Choisir et analyser le fichier sans modifier les données.</li><li>Télécharger et vérifier une copie de l’état actuel.</li><li>Confirmer le remplacement complet de cet espace.</li></ol><label>Fichier de sauvegarde<input id="restore-file" type="file" accept=".json,.enc,application/json"></label><label>Phrase de la sauvegarde (si elle est chiffrée)<input id="restore-pass" type="password" autocomplete="off"><small class="muted">Inutile si elle a été chiffrée avec la phrase de synchronisation de cet appareil.</small></label><div class="actions"><button id="analyse-backup">Analyser la sauvegarde</button></div><div id="restore-preview"></div></section></div><p class="helper">Une sauvegarde chiffrée ne s’ouvre qu’avec sa phrase, sur n’importe quel appareil ; une sauvegarde non chiffrée contient tout en clair (RIB, pièces). L’empreinte détecte la corruption. Sauvegardes formats 1, 2 (E1) et 3 (E2) et 4 (E5) et 5 (Notes/Échéances) acceptées ; aucune fusion ni migration des anciennes applications.</p><div class="columns device-cards"><section class="card" id="sync-card"></section><section class="card" id="lock-card"></section></div>`;}
function render(){document.querySelectorAll('[data-route]').forEach(b=>b.setAttribute('aria-current',b.dataset.route===route?'page':'false'));$('company-filter').innerHTML='<option value="">Toutes les sociétés</option>'+data.companies.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('');$('company-filter').value=companyFilter;$('content').innerHTML=route==='search'?searchScreen():route==='notes'?notesHTML(data,companyFilter):route==='deadlines'?deadlinesHTML(data,companyFilter):route==='routines'?routinesHTML(data,companyFilter):route==='home'?home():route==='dashboard'?dashboardScreen():route==='tasks'?taskScreen():route==='companies'?companyScreen():backupScreen();afterRender();setBusy(busy);}
function go(next){if(busy||!leaveRoutines())return;if(next!=='tasks')dashboardDrill=null;closeCreate();closeSettings();if(next!=='companies')companyDetail=null;route=next;restore=null;safetyRevision=null;error('');render();}
function editor(type,item=null){if(!ready||busy)return;closeCreate();editing={type,id:item?.id||null};$('form-error').hidden=true;$('form-error').textContent='';$('editor-title').textContent=type==='company'?(item?'Modifier la société':'Nouvelle société'):item?'Modifier la tâche':'Nouvelle tâche';$('form-fields').innerHTML=type==='company'?companyForm(item):`<div class="form-grid"><label class="full">Intitulé<input name="title" required maxlength="240"></label><label>Société<select name="companyId"><option value="">Général · sans société</option>${data.companies.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></label><label>Échéance<input name="dueDate" type="date"></label><label>Priorité<select name="priority"><option value="normal">Normale</option><option value="high">Haute</option><option value="low">Basse</option></select></label><label class="full">Notes<textarea name="notes" maxlength="4000"></textarea></label></div><p class="helper">Seul l’intitulé est obligatoire. Une tâche sans date reste visible dans « Sans date ».</p>`;if(item){for(const [key,value] of Object.entries(item)){const field=$('editor-form').elements.namedItem(key);if(field)field.value=value??'';}}else if(type==='task')$('editor-form').elements.namedItem('companyId').value=companyFilter;$('editor').showModal();$('form-fields').querySelector('input').focus();}
function cancel(){if(busy||$('e1-add-document')?.disabled)return;const form=$('editor-form');if((editing?.type==='company'&&companyDirty(form))||[...form.elements].some(f=>(f.tagName==='INPUT'||f.tagName==='TEXTAREA')&&f.value&&f.value!==f.defaultValue)){if(!window.confirm('Fermer sans enregistrer les modifications de ce formulaire ?'))return;}$('editor').close();editing=null;$('create-trigger').focus();}
async function commit(next){const expected=data.revision;setBusy(true);status('Enregistrement en cours…');error('');try{await createBackup(next);const saved=await store.write(validateState(next),expected);data=saved;restore=null;safetyRevision=null;status('Enregistré localement · transaction confirmée. Exportez une copie régulièrement.');render();sync.schedule(4000);return true;}catch(e){error(`Échec d’enregistrement : ${e.message}. Votre saisie est conservée. Aucune réussite annoncée. Rechargez la liste en cas de modification dans un autre onglet.`);status('Enregistrement non confirmé.');return false;}finally{setBusy(false);}}
async function downloadBackup(id='download-backup',keyOverride=null){if(!ready||busy)return false;setBusy(true);error('');try{const snapshot=await store.read();const text=await createBackup(snapshot);await parseBackup(text);const out=await protectBackup(text,id,keyOverride);const blob=new Blob([out.text],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`sgc-organisation-${new Date().toISOString().replace(/[:.]/g,'-')}${out.encrypted?'.chiffre':''}.backup.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);markBackup();status(out.encrypted?'Sauvegarde CHIFFRÉE préparée et téléchargement demandé : elle ne s’ouvre qu’avec sa phrase. Conservez-la hors du profil Chrome.':`Sauvegarde NON chiffrée préparée et téléchargement demandé${out.reason?' ('+out.reason+')':''}. Elle contient tout en clair : rangez-la en lieu sûr.`);if(id==='restore-safety-download'){if(snapshot.revision!==data.revision)throw Error('L’état a changé dans un autre onglet. Rechargez la page puis recommencez.');safetyRevision=snapshot.revision;$('restore-confirm').disabled=false;const btn=$('restore-safety-download');btn.textContent='Copie préalable téléchargée · à vérifier';}return true;}catch(e){error(`Sauvegarde impossible : ${e.message}`);return false;}finally{setBusy(false);}}
async function analyseBackup(){if(busy)return;restore=null;safetyRevision=null;const file=$('restore-file').files[0];$('restore-preview').innerHTML='';error('');if(!file){error('Choisissez un fichier de sauvegarde.');return;}if(file.size>40*1024*1024){error('Fichier trop volumineux : limite 40 Mio.');return;}setBusy(true);try{restore=await parseBackup(await openBackupFile(await file.text()));$('restore-preview').innerHTML=`<h3>Aperçu validé · aucune donnée remplacée</h3><p class="helper">${restore.companies.length} société(s) · ${restore.tasks.length} tâche(s) · ${restore.routines.weeks.length} semaine(s) de routine · ${restore.notes.length} note(s) · ${restore.deadlines.length} échéance(s). Les données actuelles seront entièrement remplacées.</p><button id="restore-safety-download">Télécharger la copie préalable</button><label class="check-label"><input type="checkbox" id="restore-confirm" disabled><span>J’ai vérifié le téléchargement de la copie actuelle et je confirme le remplacement complet.</span></label><button id="restore-apply" class="primary" disabled>Remplacer les données</button>`;status('Sauvegarde analysée sans écriture. Vérifiez le périmètre puis téléchargez la copie préalable.');}catch(e){error(`Restauration refusée : ${e.message}. Les données actuelles sont préservées.`);}finally{setBusy(false);}}
async function applyRestore(){if(!restore||busy||safetyRevision!==data.revision||!$('restore-confirm')?.checked)return;const candidate=restore;setBusy(true);error('');status('Restauration en cours…');try{const current=await store.read();if(current.revision!==safetyRevision)throw Error('Données modifiées depuis la copie préalable. Rechargez la page puis recommencez l’analyse et la copie.');const next={...candidate,revision:data.revision};data=await store.write(validateState(next),data.revision);companyFilter='';companyDetail=null;dateFrom='';dateTo='';taskScope='all';priorityFilter='';kanbanColumn='all';query='';restore=null;safetyRevision=null;status('Restauration confirmée · données relues après transaction. Conservez la copie préalable.');render();sync.afterRestore();}catch(e){restore=null;safetyRevision=null;error(`Restauration échouée : ${e.message}. Aucun remplacement partiel ne doit être appliqué ; rechargez pour vérifier l’état conservé.`);status('Restauration non confirmée.');$('restore-preview').innerHTML='<p class="warning">Recommencez l’analyse avant toute nouvelle tentative.</p>';}finally{setBusy(false);}}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.route){if(mobileMedia.matches&&b.dataset.route==='backup'&&b.closest('nav'))openSettings();else go(b.dataset.route);return;}if(b.dataset.downloadDocument){downloadDocument(data.companies.find(c=>c.id===b.dataset.documentCompany),b.dataset.downloadDocument);return;}if(editing?.type==='company'&&(b.dataset.addRow||b.id==='e1-add-document')){if(busy)return;setBusy(true);try{await handleCompanyEditorClick(b,$('editor-form'));}finally{setBusy(false);}return;}if(b.id==='create-trigger'||b.dataset.openCreate){openCreate();return;}if(b.id==='settings-trigger'){openSettings();return;}if(b.id==='close-settings'){closeSettings();return;}if(b.id==='back-companies'){companyDetail=null;render();return;}if(b.dataset.companyDetail){companyDetail=b.dataset.companyDetail;companyFilter=companyDetail;route='companies';render();return;}if(b.dataset.editCompany){editor('company',data.companies.find(c=>c.id===b.dataset.editCompany));return;}if(b.dataset.contextCreate){companyFilter=b.dataset.contextCreate;render();openCreate();return;}if(b.id==='close-create'){closeCreate();return;}if(b.id==='create-company')editor('company');if(b.id==='create-task')editor('task');if(b.dataset.editTask)editor('task',data.tasks.find(t=>t.id===b.dataset.editTask));if(b.dataset.toggleTask&&!busy){const old=data.tasks.find(t=>t.id===b.dataset.toggleTask);const next=updateTask(old,{status:old.status==='done'?'open':'done'},{now:editNow(data)},data);await commit({...data,tasks:data.tasks.map(t=>t.id===old.id?next:t)});}if(b.dataset.scope){dashboardDrill=null;priorityFilter='';kanbanColumn='all';taskMode='list';taskScope=b.dataset.scope==='done-period'?'done':b.dataset.scope;dateFrom=b.dataset.scope==='done-period'?doneFrom:'';dateTo=b.dataset.scope==='done-period'?doneTo:'';dateField=b.dataset.scope==='done-period'?'completedAt':'dueDate';query='';go('tasks');}if(b.dataset.companyTasks){dashboardDrill=null;priorityFilter='';kanbanColumn='all';taskMode='list';companyFilter=b.dataset.companyTasks;taskScope='open';dateFrom='';dateTo='';dateField='dueDate';query='';go('tasks');}if(b.id==='reset-filters'){dashboardDrill=null;seriesPage=0;query='';taskScope='all';priorityFilter='';companyFilter='';dateFrom='';dateTo='';dateField='dueDate';render();}if(b.id==='download-backup'||b.id==='restore-safety-download')await downloadBackup(b.id);if(b.id==='analyse-backup')await analyseBackup();if(b.id==='restore-apply')await applyRestore();if(b.id==='request-persistence'){storageProtected=await requestPersistence();if($('persistence-status'))$('persistence-status').innerHTML=protectionHTML(storageProtected);}if(b.id==='protection-install')$('pwa-guide').click();if(b.id==='token-banner-open')syncUI.goBackup();});
$('editor-form').addEventListener('submit',async e=>{e.preventDefault();if(busy)return;const input=editing.type==='company'?readCompanyForm(e.target):Object.fromEntries(new FormData(e.target)),now=editNow(data);try{let next;if(editing.type==='company'){if($('e1-file')?.files.length)throw Error('Cliquez sur Joindre le document avant d’enregistrer, ou retirez le fichier sélectionné.');const old=editing.id&&data.companies.find(c=>c.id===editing.id);const dup=findDuplicateCompany(data.companies,input.name,old?.id||null);if(dup&&!window.confirm(`Une société « ${dup.name} » existe déjà. Enregistrer quand même une autre société avec ce nom ?`)){$('form-error').hidden=false;$('form-error').textContent=`Non enregistrée : « ${dup.name} » existe déjà. Modifiez le nom ou ouvrez la fiche existante.`;return;}const company=old?updateCompany(old,input,{now},data):createCompany(input,{id:crypto.randomUUID(),now});next={...data,companies:old?data.companies.map(c=>c.id===old.id?company:c):[...data.companies,company]};}else{input.companyId=input.companyId||null;const existing=editing.id&&data.tasks.find(t=>t.id===editing.id);const task=existing?updateTask(existing,input,{now},data):createTask(input,{id:crypto.randomUUID(),now},data);next={...data,tasks:existing?data.tasks.map(t=>t.id===existing.id?task:t):[...data.tasks,task]};}if(await commit(next)){$('editor').close();editing=null;$('create-trigger').focus();}}catch(e){$('form-error').hidden=false;$('form-error').textContent=e.message;}});
$('close-editor').onclick=cancel;$('cancel-editor').onclick=cancel;$('editor').addEventListener('cancel',e=>{e.preventDefault();cancel();});
$('company-filter').onchange=e=>{if(busy||!leaveRoutines()){e.target.value=companyFilter;return;}companyFilter=e.target.value;companyDetail=null;render();};
document.addEventListener('input',e=>{if(e.target.id==='company-search'){const start=e.target.selectionStart;companyQuery=e.target.value;render();$('company-search').focus();$('company-search').setSelectionRange(start,start);}if(e.target.id==='global-search'){const start=e.target.selectionStart;globalQuery=e.target.value;$('header-search').value=globalQuery;render();$('global-search').focus();$('global-search').setSelectionRange(start,start);}if(e.target.id==='task-search'){const start=e.target.selectionStart;query=e.target.value;if(route==='dashboard'){seriesPage=0;render();$('task-search').focus();$('task-search').setSelectionRange(start,start);}else{$('task-results').innerHTML=workspace();$('task-count').textContent=`${tasksForView().length} tâche(s)`;if(dashboardDrill)document.querySelector('.drill-notice strong').textContent=`Détail du tableau de bord · ${tasksForView().length} tâche(s)`;}}});
document.addEventListener('change',e=>{if(['filter-from','filter-to','date-field','done-from','done-to'].includes(e.target.id)){if(e.target.id==='filter-from')dateFrom=e.target.value;if(e.target.id==='filter-to')dateTo=e.target.value;if(e.target.id==='date-field')dateField=e.target.value;if(e.target.id==='done-from')doneFrom=e.target.value;if(e.target.id==='done-to')doneTo=e.target.value;const keepPeriodOpen=e.target.id.startsWith('done-');render();if(keepPeriodOpen)document.querySelector('.completion-period').open=true;}if(e.target.id==='task-scope'){taskScope=e.target.value;if(taskScope==='undated'){dateFrom='';dateTo='';dateField='dueDate';}render();}if(e.target.id==='restore-confirm')$('restore-apply').disabled=!e.target.checked;if(e.target.id==='restore-file'){restore=null;safetyRevision=null;$('restore-preview').innerHTML='';}});
$('theme').onclick=()=>{const dark=document.documentElement.dataset.theme!=='dark';document.documentElement.dataset.theme=dark?'dark':'light';$('theme').textContent=dark?'Mode clair':'Mode sombre';$('theme').setAttribute('aria-pressed',String(dark));persistUI();};
$('effects').onclick=()=>{const reduced=document.documentElement.dataset.effects!=='reduced';document.documentElement.dataset.effects=reduced?'reduced':'full';$('effects').textContent=reduced?'Activer le verre léger':'Réduire les effets';$('effects').setAttribute('aria-pressed',String(reduced));persistUI();};
window.addEventListener('beforeunload',e=>{if(busy||routineDirty()||document.getElementById('organiser-editor')?.open||$('editor').open){e.preventDefault();e.returnValue='';}});
async function init(){try{store=await openStore();data=validateState(await store.read());ready=true;status('Votre espace est prêt · données locales chargées.');render();}catch(e){error(`Stockage indisponible : ${e.message}. Ne saisissez aucune donnée tant que le stockage n’est pas rétabli.`);status('Ouverture échouée.');$('create-trigger').disabled=true;}}
document.querySelectorAll('nav [data-route]').forEach(b=>{b.innerHTML=`${icon(b.dataset.route==='home'?'sun':b.dataset.route)}<span>${b.textContent}</span>`;});
document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));
function closeCreate(){if($('create-menu').open)$('create-menu').close();$('create-trigger').setAttribute('aria-expanded','false');}
function openCreate(){if(!ready||busy||!leaveRoutines())return;closeSettings();$('create-context').textContent=companyFilter?`Pour ${companyName(companyFilter)} · société proposée pour la tâche`:'Choisissez une action. La société reste facultative pour une tâche.';$('create-trigger').setAttribute('aria-expanded','true');$('create-menu').showModal();$('create-task').focus();}
$('create-menu').addEventListener('close',()=>{$('create-trigger').setAttribute('aria-expanded','false');if(!$('editor').open)$('create-trigger').focus();});
$('create-menu').addEventListener('click',e=>{const r=e.currentTarget.getBoundingClientRect();if(e.target===e.currentTarget&&(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom))closeCreate();});
$('create-menu').addEventListener('keydown',e=>{if(!['ArrowDown','ArrowUp','Home','End'].includes(e.key))return;const options=[...$('create-menu').querySelectorAll('.creation-options button:not(:disabled)')];const current=options.indexOf(document.activeElement);let next=e.key==='Home'?0:e.key==='End'?options.length-1:(current+(e.key==='ArrowDown'?1:-1)+options.length)%options.length;options[next].focus();e.preventDefault();});
window.addEventListener('focus',()=>{if(ready&&route==='home'&&!busy&&!$('editor').open&&!$('create-menu').open)render();});
const mobileMedia=matchMedia('(max-width:720px)');
const navElement=document.querySelector('nav'), backupNav=navElement.querySelector('[data-route="backup"]');
function adaptNavigation(){if(mobileMedia.matches){navElement.insertBefore($('create-trigger'),navElement.querySelector('[data-route="companies"]'));backupNav.innerHTML=`${icon('note')}<span>Plus</span>`;backupNav.setAttribute('aria-haspopup','dialog');}else{document.querySelector('.tools').append($('create-trigger'));backupNav.innerHTML=`${icon('backup')}<span>Sauvegarde</span>`;backupNav.removeAttribute('aria-haspopup');}closeCreate();closeSettings();}
mobileMedia.addEventListener('change',adaptNavigation);
function openSettings(){closeCreate();$('settings-menu').showModal();$('settings-menu').querySelector('button[data-route]').focus();}
function closeSettings(){if($('settings-menu').open)$('settings-menu').close();}
$('settings-menu').addEventListener('click',e=>{const r=e.currentTarget.getBoundingClientRect();if(e.target===e.currentTarget&&(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom))closeSettings();});
$('close-settings').onclick=closeSettings;
$('settings-menu').addEventListener('close',()=>{if(!$('create-menu').open&&!$('editor').open)(mobileMedia.matches?backupNav:$('settings-trigger')).focus();});
function persistUI(){if(!savePreferences({theme:document.documentElement.dataset.theme,effects:document.documentElement.dataset.effects,taskMode}))status('Préférence appliquée pour cette session ; mémorisation indisponible.');}
const prefs=readPreferences();document.documentElement.dataset.theme=prefs.theme;document.documentElement.dataset.effects=prefs.effects;$('theme').textContent=prefs.theme==='dark'?'Mode clair':'Mode sombre';$('theme').setAttribute('aria-pressed',String(prefs.theme==='dark'));$('effects').textContent=prefs.effects==='reduced'?'Activer le verre léger':'Réduire les effets';$('effects').setAttribute('aria-pressed',String(prefs.effects==='reduced'));
$('header-search-form').addEventListener('submit',e=>{e.preventDefault();globalQuery=$('header-search').value;go('search');setTimeout(()=>{const f=$('global-search');if(f){f.focus();f.setSelectionRange(f.value.length,f.value.length);}},0);});
