if(window.visualViewport){window.visualViewport.addEventListener('resize',()=>document.body.classList.toggle('keyboard-open',mobileMedia.matches&&window.visualViewport.height<window.innerHeight*.75));}
adaptNavigation();
// Synchronisation chiffrée, verrouillage PIN et rappel de sauvegarde (propres à cet appareil).
function syncEditing(){const a=document.activeElement;return busy||!ready||routineDirty()||!!document.querySelector('dialog[open]')||lock.isLocked()||!!(a&&a.closest&&a.closest('#content')&&/^(INPUT|TEXTAREA|SELECT)$/.test(a.tagName)&&!a.closest('#sync-card'));}
const sync=createSyncEngine({vault:browserVault,readState:()=>store.read(),isEditing:syncEditing,
 writeState:async(next,expected)=>{if(busy)throw Error('Application occupée');const saved=await store.write(validateState(next),expected);data=saved;if(companyFilter&&!data.companies.some(c=>c.id===companyFilter)){companyFilter='';companyDetail=null;}render();return saved;},
 safetyCopy:k=>downloadBackup('sync-safety',k),onUpdate:v=>syncUI?.render(v)});
const syncUI=setupSyncUI({engine:sync,goBackup:()=>{if(lock.isLocked())return;go('backup');$('sync-card')?.scrollIntoView({block:'start'});}});
let syncConfigured=false;browserVault.get('config').then(c=>{syncConfigured=!!c;}).catch(()=>{});
const lock=setupLock({verifyPassphrase:p=>sync.verifyPassphrase(p),hasSync:()=>sync.view().connected||syncConfigured});
setupDeviceUI({lock,onBackup:()=>{if(backupNeedsPassphrase()){go('backup');status('Saisissez la phrase de sauvegarde, puis « Télécharger la sauvegarde complète ».');setTimeout(()=>$('backup-pass')?.focus(),50);return;}return downloadBackup();},refresh:()=>{if(route==='backup')render();},status});
addEventListener('sgc-lock-changed',()=>{if(route==='backup')render();});
async function afterRender(){
 if(route==='home'&&ready){const hasData=data.companies.length+data.tasks.length+data.notes.length+data.deadlines.length>0;const banners=(reminderDue(hasData,undefined,undefined,storageProtected)?reminderBanner(storageProtected):'')+tokenBanner(sync.view());if(banners)$('content').insertAdjacentHTML('afterbegin',banners);}
 if(route!=='backup')return;
 renderEncryption();
 syncUI.render(sync.view());if($('lock-card'))$('lock-card').innerHTML=lockCardHTML(lock);

}
document.querySelector('.side-note .tag')&&(document.querySelector('.side-note .tag').textContent=`SGC Organisation · version ${APP_VERSION}`);
init().then(async()=>{if(!ready)return;storageProtected=await requestPersistence();if(storageProtected===null)storageProtected=await persistenceStatus();await sync.init();syncUI.render(sync.view());if(route==='home'||route==='backup')render();});
setupPWA({canUpdate:()=>ready&&!busy&&!routineDirty()&&!document.getElementById('organiser-editor')?.open&&!document.getElementById('company-delete-dialog')?.open&&!$('editor').open&&!$('create-menu').open&&!$('pwa-guide-dialog').open&&!document.getElementById('export-dialog')?.open});

async function changeTaskStatus(id,status){
 if(busy)return;const old=data.tasks.find(t=>t.id===id);if(!old||old.status===status)return;
 try{const next=updateTask(old,{status},{now:editNow(data)},data);if(!await commit({...data,tasks:data.tasks.map(t=>t.id===id?next:t)})){render();}}catch(e){error(e.message);render();}
 const control=document.querySelector(`[data-task-status="${id}"]`);(control||$('task-scope'))?.focus();
}
document.addEventListener('click',e=>{
 const b=e.target.closest('button');if(!b||busy)return;
 if(b.dataset.taskView){taskMode=b.dataset.taskView;persistUI();render();}
 if(b.dataset.calendarPeriod){calendarPeriod=b.dataset.calendarPeriod;render();}
 if(b.hasAttribute('data-calendar-step')){try{const next=moveCalendar(calendarAnchor,calendarPeriod,Number(b.dataset.calendarStep));calendarRange(next,calendarPeriod);calendarAnchor=next;render();}catch{error('Période hors des dates supportées.');}}
 if(b.hasAttribute('data-calendar-today')){calendarAnchor=localToday();render();}
 if(b.dataset.calendarDay){try{calendarRange(b.dataset.calendarDay,'day');calendarAnchor=b.dataset.calendarDay;calendarPeriod='day';render();}catch(e){error(e.message);}}
 if(b.dataset.createDay){editor('task');$('editor-form').elements.namedItem('dueDate').value=b.dataset.createDay;}
});
document.addEventListener('change',async e=>{
 const el=e.target;if(busy){render();return;}
 if(el.dataset.taskStatus)await changeTaskStatus(el.dataset.taskStatus,el.value);
 if(el.id==='priority-filter'){priorityFilter=el.value;render();}
 if(el.id==='group-companies'){groupCompanies=el.checked;render();}
 if(el.id==='kanban-column'){kanbanColumn=el.value;render();}
 if(el.id==='calendar-anchor'&&el.value){try{calendarRange(el.value,calendarPeriod);calendarAnchor=el.value;render();}catch(e){error(e.message);el.value=calendarAnchor;}}
});
let draggingTask=null;
document.addEventListener('dragstart',e=>{const card=e.target.closest('[data-drag-task]');if(!card||busy)return;draggingTask=card.dataset.dragTask;e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',draggingTask);});
document.addEventListener('dragover',e=>{if(draggingTask&&e.target.closest('[data-drop-status]'))e.preventDefault();});
document.addEventListener('drop',async e=>{const col=e.target.closest('[data-drop-status]');if(!col||!draggingTask)return;e.preventDefault();const id=draggingTask;draggingTask=null;await changeTaskStatus(id,col.dataset.dropStatus);});
document.addEventListener('dragend',()=>draggingTask=null);
document.addEventListener('keydown',e=>{if(e.key==='Escape')draggingTask=null;});

document.addEventListener('click',async e=>{
 if(busy)return;
 const target=e.target.closest('[data-dashboard-drill]');
 if(target){dashboardDrill=target.dataset.dashboardDrill;taskMode='list';kanbanColumn='all';go('tasks');$('content').focus();scrollTo(0,0);}
 const b=e.target.closest('button');if(!b)return;
 if(b.id==='refresh-dashboard'){setBusy(true);try{data=validateState(await store.read());seriesPage=0;status('Tableau de bord actualisé · données locales relues.');render();}catch(e){error(`Actualisation impossible : ${e.message}`);}finally{setBusy(false);}}
 if(b.id==='clear-dashboard-drill'){dashboardDrill=null;render();}
 if(b.hasAttribute('data-series-page')){seriesPage=Number(b.dataset.seriesPage);render();document.querySelector('.dashboard-series h3').setAttribute('tabindex','-1');document.querySelector('.dashboard-series h3').focus();}
});
document.addEventListener('change',e=>{if(e.target.id==='dashboard-granularity'&&!busy){dashboardGranularity=e.target.value;seriesPage=0;render();}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('.chart-point')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});

setupExports();
document.addEventListener('click',e=>{if(!e.target.closest('[data-export-open]')||busy||!ready)return;try{const isCompany=route==='companies'&&companyDetail,isRoutine=route==='routines';if(routineDirty()){error('Enregistrez les modifications de la routine avant export.');return;}openExport(data,{kind:isRoutine?'routines':isCompany?'company':'tasks',weekId:document.querySelector('[data-week-id]')?.dataset.weekId,routineDate:routineDashboardDate,companyId:isCompany?companyDetail:null,ids:isCompany||isRoutine?[]:tasksForView().map(t=>t.id),filters:{...commonFilters(),company:companyFilter?companyName(companyFilter):'Toutes les sociétés',detail:dashboardDrill||'',detailLabel:dashboardDrill?dashboard().groups.find(g=>g.key===dashboardDrill)?.label||'':'',today:localToday()},granularity:dashboardGranularity});}catch(e){error(e.message);}});

setupRoutines({getData:()=>data,getCompany:()=>companyFilter,commit,render,error,isBusy:()=>busy,navigate:id=>{if(!leaveRoutines())return;companyFilter=id;go('routines');}});

document.addEventListener('change',e=>{if(e.target.id==='routine-dashboard-date'){try{if(monday(e.target.value)!==e.target.value)throw Error('Choisissez un lundi.');routineDashboardDate=e.target.value;render();}catch(x){e.target.value=routineDashboardDate;error(x.message);}}});

setupCompanyDeletion({getData:()=>data,read:()=>store.read(),commit,setBusy,isBusy:()=>busy,protect:text=>protectBackup(text,'company-delete'),onDeleted:id=>{if(companyFilter===id)companyFilter='';companyDetail=null;route='companies';status('Société supprimée · autres données conservées.');render();}});

setupOrganiser({getData:()=>data,getCompany:()=>companyFilter,commit,render,closeCreate,isBusy:()=>busy,isReady:()=>ready,globalError:error,openTask:id=>editor('task',data.tasks.find(t=>t.id===id)),navigate:kind=>{if(kind==='calendar'){taskMode='calendar';go('tasks');}else go(kind);}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||busy)return;if(b.dataset.companyNotes||b.dataset.companyDeadlines){companyFilter=b.dataset.companyNotes||b.dataset.companyDeadlines;go(b.dataset.companyNotes?'notes':'deadlines');}if(b.hasAttribute('data-export-calendar')){try{const days=calendarRange(calendarAnchor,calendarPeriod);openExport(data,{kind:'calendar',ids:calendarKind==='deadlines'?[]:tasksForView().filter(t=>days.includes(t.dueDate)).map(t=>t.id),deadlineIds:calendarKind==='tasks'?[]:deadlineSelection(data,companyFilter).filter(d=>days.includes(d.dueDate)).map(d=>d.id),filters:{...commonFilters(),company:companyFilter?companyName(companyFilter):'Toutes les sociétés'},calendarDates:days});}catch(x){error(x.message);}}});

document.addEventListener('click',e=>{if(e.target.closest('[data-search-tasks]')&&!busy)showTasksFor(globalQuery);});
document.addEventListener('click',e=>{const b=e.target.closest('[data-export-ics]');if(!b||busy||!ready)return;try{const list=deadlineSelection(data,companyFilter).filter(d=>d.status!=='done');if(!list.length){status('Aucune échéance non terminée dans la sélection affichée : rien à exporter.');return;}const text=deadlinesToICS(list,{companyName:id=>data.companies.find(c=>c.id===id)?.name||''}),url=URL.createObjectURL(new Blob([text],{type:'text/calendar;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=`sgc-echeances-${localToday()}.ics`;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);status(`${list.length} échéance(s) exportée(s) vers un fichier agenda (.ics). Importez-le dans votre agenda puis supprimez le fichier.`);}catch(x){error(x.message);}});
document.addEventListener('change',e=>{if(e.target.id==='calendar-kind'){calendarKind=e.target.value;render();}});

document.addEventListener('click',e=>{const cell=e.target.closest('[data-calendar-cell]');if(cell&&!busy&&calendarPeriod==='month'&&!e.target.closest('button,input,select,a')){calendarAnchor=cell.dataset.calendarCell;calendarPeriod='day';render();}});
